<?php
namespace App\Modules\Scheduling\Actions;
use App\Modules\Scheduling\Models\{Appointment,AppointmentEvent,EventType}; use App\Modules\Scheduling\Services\SlotGenerator; use Carbon\CarbonImmutable; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class RescheduleAppointment { public function __construct(private SlotGenerator $slots){} public function execute(Appointment $appointment,string $token,string $start,string $timezone,?int $actor=null): Appointment{return DB::transaction(function()use($appointment,$token,$start,$timezone,$actor){$type=EventType::query()->lockForUpdate()->findOrFail($appointment->event_type_id);$item=Appointment::query()->lockForUpdate()->findOrFail($appointment->id);if(!$actor&&!hash_equals($item->reschedule_token_hash,hash('sha256',$token)))throw ValidationException::withMessages(['token'=>'Link de reagendamento inválido.']);$date=CarbonImmutable::parse($start,$timezone);$oldStart=$item->scheduled_start_at;$item->update(['status'=>'cancelled']);$ok=collect($this->slots->generate($type,$date->format('Y-m-d'),$timezone))->contains('start',$date->toIso8601String());if(!$ok)throw ValidationException::withMessages(['start'=>'Este horário não está mais disponível.']);$item->update(['scheduled_start_at'=>$date->utc(),'scheduled_end_at'=>$date->addMinutes($type->duration_minutes)->utc(),'timezone'=>$timezone,'status'=>'confirmed','cancelled_at'=>null]);AppointmentEvent::query()->create(['appointment_id'=>$item->id,'event_type'=>'rescheduled','metadata'=>['previous_start'=>$oldStart->toIso8601String()],'actor_type'=>$actor?'user':'guest','actor_id'=>$actor,'created_at'=>now()]);return $item;},3);}}
